using namespace hb::gpu;
static float linear(int byte){const float c=byte/255.f;return c<=.04045f?c/12.92f:std::pow((c+.055f)/1.055f,2.4f);}
static int display(float value){const float c=std::clamp(value,0.f,1.f);return int(std::round(255*(c<=.0031308f?c*12.92f:1.055f*std::pow(c,1/2.4f)-.055f)));}
int main(){try{
 ProbeSettings first;for(unsigned flags=0;flags<8;flags++){first.options[3]=float(flags);setProbePriorityBlend(first,true);if(first.options[3]!=float((flags%4)+4))throw std::runtime_error("priority flags set");setProbePriorityBlend(first,false);if(first.options[3]!=float(flags%4))throw std::runtime_error("priority flags restore");}first.options[3]=5;setProbeSphereVolume(first,{0,0,.5f},.5f);if(first.options[3]!=7||!probeVolumeBasisUsable(first))throw std::runtime_error("sphere lost priority");for(float flags:{-1.f,1.5f,8.f,std::numeric_limits<float>::quiet_NaN()}){first.options[3]=flags;if(probeVolumeBasisUsable(first))throw std::runtime_error("invalid flags accepted");bool rejected=false;try{setProbePriorityBlend(first,true);}catch(const std::exception&){rejected=true;}if(!rejected)throw std::runtime_error("invalid setter accepted");}
 Device gpu;SceneRenderer r(gpu,64,16);SceneFrame frame;frame.eye={0,0,10,1};frame.ambient={0,0,0,1};r.setLights({});r.begin(frame);std::vector<SceneRenderer::Probe> captures;captures.reserve(4);for(unsigned i=0;i<4;i++){captures.push_back(r.createProbe(16));std::array<float,4> color{0,0,0,1};if(i<3)color[i]=1;else color={1,1,1,1};for(UINT face=0;face<6;face++){r.beginProbe(captures.back(),face,identity,{0,0,.5f,1},color);r.endProbe();}r.filterProbe(captures.back());}
 auto mesh=r.createMesh({{{-1,-1,.5f}},{{1,-1,.5f}},{{1,1,.5f}},{{-1,1,.5f}}},{0,1,2,0,2,3});SceneMaterial material;material.unlit=false;material.toneMapped=false;material.metalness=1;material.roughness=.3f;
 ProbeSettings innerSettings,outerSettings,distantSettings;innerSettings.center={0,0,.5f,1};innerSettings.minimum={-.5f,-2,-1,.5f};innerSettings.maximum={.5f,2,2,0};outerSettings.center={0,0,.5f,1};outerSettings.minimum={-2,-2,-1,.1f};outerSettings.maximum={2,2,2,0};distantSettings.minimum={10,10,10,0};distantSettings.maximum={11,11,11,0};
 const auto draw=[&](bool global,const std::array<SceneRenderer::ProbeBinding,2>* direct){r.begin(frame);r.draw(mesh,identity,identity,material,{},{},0,0,nullptr,{},{},nullptr,nullptr,nullptr,direct,nullptr,0,nullptr,global);return r.readPixels();};std::array<SceneRenderer::ProbeBinding,2> white{};white[0]={&captures[3],outerSettings};const auto reference=draw(false,&white);unsigned samples=0;int maxError=0;const auto verify=[&](const std::vector<unsigned char>& pixels,bool priority,bool sphere,bool dark){for(unsigned y=0;y<16;y++)for(unsigned x=0;x<64;x++){const float at=-1+(x+.5f)/32,up=-1+(y+.5f)/8,a=std::clamp(sphere?( .5f-std::hypot(at,up))/.5f:1-2*std::abs(at),0.f,1.f),b=priority?1-a:1,total=a+b;const std::array<float,3> weights{dark?0:a/std::max(1.f,total),b/std::max(1.f,total),0};for(unsigned channel=0;channel<3;channel++){const auto index=(y*64+x)*4+channel;const int expected=display(linear(reference[index])*weights[channel]),error=std::abs(int(pixels[index])-expected);maxError=std::max(maxError,error);if(error>3)throw std::runtime_error(nlohmann::json({{"x",x},{"y",y},{"channel",channel},{"priority",priority},{"sphere",sphere},{"dark",dark},{"actual",pixels[index]},{"expected",expected}}).dump());}samples++;}};
 std::array<SceneRenderer::ProbeBinding,2> pair{};pair[0]={&captures[0],innerSettings};pair[1]={&captures[1],outerSettings};verify(draw(false,&pair),false,false,false);setProbePriorityBlend(pair[0].settings,true);verify(draw(false,&pair),true,false,false);setProbeSphereVolume(pair[0].settings,{0,0,.5f},.5f);verify(draw(false,&pair),true,true,false);setProbePriorityBlend(pair[0].settings,false);verify(draw(false,&pair),false,true,false);
 pair[0]={&captures[0],innerSettings};std::vector<SceneRenderer::ProbeBinding> atlas{pair[0],pair[1],{&captures[2],distantSettings}};r.setGlobalProbes(atlas);verify(draw(true,nullptr),false,false,false);const auto copies=r.probeAtlasCopies(),layouts=r.probeAtlasLayoutBuilds();setProbePriorityBlend(atlas[0].settings,true);r.setGlobalProbes(atlas);verify(draw(true,nullptr),true,false,false);if(r.probeAtlasCopies()!=copies||r.probeAtlasLayoutBuilds()!=layouts||!r.probeAtlasMetadataFastUpdates())throw std::runtime_error("mode rebuilt capture/layout");setProbeSphereVolume(atlas[0].settings,{0,0,.5f},.5f);r.setGlobalProbes(atlas);verify(draw(true,nullptr),true,true,false);atlas[0].settings.center[3]=0;r.setGlobalProbes(atlas);verify(draw(true,nullptr),true,true,true);
 material.unlit=true;auto transmission=r.createProgram("StructuredBuffer<float> queryValues:register(t7);","float coverage;float3 color=refractedProbes(float3(queryValues[0],queryValues[1],queryValues[2]),float3(0,0,1),.3,coverage);base=float4(color,coverage);",{0,0,0,0,0,1});unsigned refractionSamples=0;int refractionError=0;for(bool global:{false,true})for(bool priority:{false,true})for(bool sphere:{false,true}){pair[0]={&captures[0],innerSettings};setProbePriorityBlend(pair[0].settings,priority);if(sphere)setProbeSphereVolume(pair[0].settings,{0,0,.5f},.5f);atlas={pair[0],pair[1],{&captures[2],distantSettings}};r.setGlobalProbes(atlas);r.setProgramParameters(transmission,{.125f,.125f,.5f});r.begin(frame);r.draw(mesh,identity,identity,material,{},{},0,0,&transmission,{},{},nullptr,nullptr,nullptr,global?nullptr:&pair,nullptr,0,nullptr,global);const auto pixels=r.readPixels();const float a=sphere?1-2*std::hypot(.125f,.125f):.75f,b=priority?1-a:1,total=a+b;const std::array<float,4> expected{a/total,b/total,0,1};for(unsigned channel=0;channel<4;channel++){const int value=channel<3?display(expected[channel]):255,error=std::abs(int(pixels[(8*64+32)*4+channel])-value);refractionError=std::max(refractionError,error);if(error>2)throw std::runtime_error("refracted priority mismatch");}refractionSamples++;}
 r.setGlobalProbes({});r.releaseProbes();if(r.probeAtlasBytes()||r.probeAtlasCPUBytes())throw std::runtime_error("priority resources retained");
 std::cout<<nlohmann::json({{"passed",true},{"refractionSamples",refractionSamples},{"refractionErrorBytes",refractionError},{"samples",samples},{"maxErrorBytes",maxError},{"toleranceBytes",3},{"captureColors",4},{"nativeRecordBytes",144},{"flagsAtomic",true},{"modeMetadataOnly",true},{"released",true},{"scope","Actual D3D11 direct/global physical reflection from four real filtered constant HDR captures; independent per-pixel box/sphere priority/legacy/dark references, shape/projection/priority bits and w-only reset, metadata mode retention and release. No whole-engine FPS claim."}}).dump();
}catch(const std::exception& error){std::cerr<<error.what();return 1;}}
